"use client";

import { useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";

import { BlockFrame } from "../parts/block-frame";
import { SettingsIcon } from "./icons";
import { formatCount } from "./lib/format";
import { useInterval } from "./lib/timers";
import { AddSourceMenu, type AddKind } from "./knowledge-base/add-source-menu";
import { NEW_SOURCES, SOURCES, type Source } from "./knowledge-base/data";
import { RetrievalTest } from "./knowledge-base/retrieval-test";
import { SourceRow } from "./knowledge-base/source-row";

type View = "sources" | "test";

const EMBED_MODEL = "Fern embed 2";

/** Moves every source at work one step through its pipeline. A source that reaches the end is ready. */
function advance(sources: Source[]): Source[] {
  return sources.map((source) => {
    if (source.state !== "indexing") return source;
    // Each source moves at its own pace, read from its size, so the rows do not march in step.
    const progress = Math.min(100, source.progress + 2 + (source.passages % 5));
    return progress >= 100 ? { ...source, progress: 100, state: "done", added: "just now" } : { ...source, progress };
  });
}

/**
 * A knowledge base an agent searches. The sources view shows each file with
 * its four-stage pipeline and state, with Retry for a failed one. The test
 * view asks a question and shows the ranked passages, with an optional rerank.
 */
export function KnowledgeBase({ className }: { className?: string }) {
  const [sources, setSources] = useState(SOURCES);
  const [view, setView] = useState<View>("sources");
  const titleId = useId();

  const indexing = sources.filter((source) => source.state === "indexing").length;
  const failed = sources.filter((source) => source.state === "failed").length;
  const passages = sources.filter((source) => source.state === "done").reduce((total, source) => total + source.passages, 0);
  const unused = NEW_SOURCES.filter((item) => !sources.some((source) => source.id === item.id));

  useInterval(() => setSources(advance), indexing > 0 ? 450 : null);

  const add = (kind: AddKind) => {
    const pick = unused.find((item) => (kind === "page" ? item.kind === "page" : item.kind === "file")) ?? unused[0];
    if (!pick) return;
    setSources((current) => [{ ...pick, state: "indexing", progress: 0, added: "" }, ...current]);
    setView("sources");
  };

  const retry = (id: string) =>
    setSources((current) =>
      current.map((source) => (source.id === id ? { ...source, state: "indexing", progress: Math.min(source.progress, 50), error: undefined } : source)),
    );

  const summary = [indexing > 0 ? `${indexing} indexing` : null, failed > 0 ? `${failed} failed` : null].filter(Boolean).join(", ");

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Clinic handbook
          </h2>
          <p className="text-sm text-muted-foreground">
            {sources.length} sources, {formatCount(passages)} passages searchable, {EMBED_MODEL}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="ghost" size="icon" aria-label="Index settings">
                <SettingsIcon aria-hidden="true" />
              </Button>
            </PopoverTrigger>
            <PopoverContent align="end" className="w-64">
              <h3 className="text-sm font-medium">Index settings</h3>
              <dl className="mt-3 grid grid-cols-[1fr_auto] gap-x-4 gap-y-2 text-sm">
                <dt className="text-muted-foreground">Passage size</dt>
                <dd className="tabular-nums">400 tokens</dd>
                <dt className="text-muted-foreground">Overlap</dt>
                <dd className="tabular-nums">60 tokens</dd>
                <dt className="text-muted-foreground">Embedding model</dt>
                <dd>{EMBED_MODEL}</dd>
                <dt className="text-muted-foreground">Sync web pages</dt>
                <dd>Daily</dd>
              </dl>
            </PopoverContent>
          </Popover>
          <AddSourceMenu onAdd={add} disabled={unused.length === 0} />
        </div>
      </header>

      <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-4">
        <SegmentedControl
          aria-label="View"
          options={[
            { value: "sources", label: `Sources ${sources.length}` },
            { value: "test", label: "Test a question" },
          ]}
          value={view}
          onValueChange={setView}
        />
        <p role="status" className="text-sm text-muted-foreground">
          {summary || "All sources ready"}
        </p>
      </div>

      {view === "sources" ? (
        <ul aria-label="Sources" className="flex flex-col py-2">
          {sources.map((source) => (
            <SourceRow key={source.id} source={source} onRetry={() => retry(source.id)} />
          ))}
        </ul>
      ) : (
        <RetrievalTest />
      )}
    </BlockFrame>
  );
}

