const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Seconds as a short clock reading, such as "48s" or "2m 05s". */
export function formatSeconds(seconds: number) {
  const whole = Math.max(0, Math.round(seconds));
  if (whole < 60) return `${whole}s`;
  const minutes = Math.floor(whole / 60);
  const rest = whole % 60;
  if (minutes < 60) return `${minutes}m ${String(rest).padStart(2, "0")}s`;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m`;
}

/** A token count, such as "840" or "12.4K". */
export const formatTokens = (value: number) => (value < 1000 ? WHOLE.format(Math.round(value)) : COMPACT.format(value));

/** A cost with cents, such as "$0.42". */
export const formatCost = (value: number) => CENTS.format(value);

/** A whole number with separators. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** Roll formats for `NumberTicker`. Module constants, because the ticker memoises its formatter on them. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
/** One decimal place, for a score or a percent. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
/** Dollars with cents. */
export const ROLL_CENTS: Intl.NumberFormatOptions = { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 };

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Calls `callback` every `delay` milliseconds while `delay` is a number, and
 * stops when it is null or the component unmounts. The latest callback always runs.
 */
export function useInterval(callback: () => void, delay: number | null) {
  const saved = useRef(callback);
  useEffect(() => {
    saved.current = callback;
  }, [callback]);
  useEffect(() => {
    if (delay === null) return;
    const id = window.setInterval(() => saved.current(), delay);
    return () => window.clearInterval(id);
  }, [delay]);
}

/**
 * Whole seconds since `running` last turned true. The count holds while
 * `running` is false and starts again from zero on `resetKey` change.
 */
export function useElapsed(running: boolean, resetKey: string | number = 0) {
  const [state, setState] = useState({ key: resetKey, seconds: 0 });
  // A new reset key starts the count again, adjusted during render rather than in an effect.
  if (state.key !== resetKey) setState({ key: resetKey, seconds: 0 });
  useInterval(() => setState((current) => ({ ...current, seconds: current.seconds + 1 })), running ? 1000 : null);
  return state.key === resetKey ? state.seconds : 0;
}

/**
 * Runs a list of timed steps one after another. Each step waits its `after`
 * milliseconds, then calls `run`. Every pending timer clears on unmount or when `key` changes.
 */
export function useSchedule(steps: { after: number; run: () => void }[] | null, key: string | number) {
  const saved = useRef(steps);
  useEffect(() => {
    saved.current = steps;
  });
  useEffect(() => {
    const list = saved.current;
    if (!list) return;
    const ids: number[] = [];
    let total = 0;
    for (const step of list) {
      total += step.after;
      ids.push(window.setTimeout(step.run, total));
    }
    return () => ids.forEach((id) => window.clearTimeout(id));
  }, [key]);
}

