/** Where a source is in the pipeline. */
export type SourceState = "done" | "indexing" | "failed";

/** One file or page the knowledge base reads from. */
export interface Source {
  id: string;
  name: string;
  kind: "file" | "page";
  pages: number;
  passages: number;
  tokens: number;
  added: string;
  state: SourceState;
  /** Progress through all four stages, from 0 to 100. */
  progress: number;
  /** For a failed source, why it stopped. */
  error?: string;
}

