const STOP = new Set(["a", "an", "the", "can", "on", "without", "is", "to", "of", "and", "or", "for", "do", "does", "i", "my", "it", "if", "in", "what", "how", "when"]);

/** The words of a question that carry meaning: lower case, no punctuation, no common words, a plural cut to its singular. */
export function queryWords(question: string) {
  return question
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length > 1 && !STOP.has(word))
    .map((word) => (word.length > 3 && word.endsWith("s") ? word.slice(0, -1) : word));
}

const passageWords = (passage: Passage) => new Set(queryWords(passage.text));

/** One ranked result. Scores run from 0 to 1. */
export interface Ranked {
  passage: Passage;
  score: number;
  /** The question words found in the passage, shown as the reason it matched. */
  matched: string[];
}

/**
 * Ranks the passages for a question. The first pass scores how many question
 * words the passage shares. The rerank pass also weighs whether those words are
 * what the passage is about, which moves the precise passages up.
 */
export function rankPassages(question: string, rerank: boolean, limit = 4): Ranked[] {
  const words = [...new Set(queryWords(question))];
  if (words.length === 0) return [];
  const ranked = PASSAGES.map((passage, order) => {
    const inText = passageWords(passage);
    const matched = words.filter((word) => inText.has(word) || passage.topics.includes(word));
    const share = matched.length / words.length;
    const onTopic = words.filter((word) => passage.topics.includes(word)).length / words.length;
    // The drift makes the first pass a little loose, as a vector search is; the position nudge keeps ties stable.
    const first = 0.42 + share * 0.45 + passage.drift - order * 0.004;
    const score = rerank ? 0.3 + onTopic * 0.65 + share * 0.08 : first;
    return { passage, score: Math.min(0.99, score), matched };
  });
  return ranked
    .filter((item) => item.matched.length > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

