"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { LoaderIcon, SearchIcon } from "../icons";
import { rankPassages, SAMPLE_QUESTION } from "./data";
import { ResultItem } from "./result-item";

type Phase = "searching" | "reranking" | "ready";

/**
 * The test view: type a question, search, and read the ranked passages.
 * Turning on rerank shows a short working state, then moves each passage to
 * its new rank while its score rolls and the change in rank fades in.
 */
export function RetrievalTest() {
  const [draft, setDraft] = useState(SAMPLE_QUESTION);
  const [question, setQuestion] = useState(SAMPLE_QUESTION);
  const [rerank, setRerank] = useState(false);
  // The rerank flag the shown list was ranked with. It lags `rerank` while the short working state shows.
  const [rankedWith, setRankedWith] = useState(false);
  const [previous, setPrevious] = useState<Map<string, number> | null>(null);
  const [phase, setPhase] = useState<Phase>("ready");
  const [openId, setOpenId] = useState<string | null>(null);
  const timer = useRef<number | null>(null);
  const inputId = useId();
  const rerankId = useId();

  useEffect(() => () => {
    if (timer.current !== null) window.clearTimeout(timer.current);
  }, []);

  const results = rankPassages(question, rankedWith);

  const later = (ms: number, run: () => void) => {
    if (timer.current !== null) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(run, ms);
  };

  const search = () => {
    const next = draft.trim();
    if (!next) return;
    setPhase("searching");
    setOpenId(null);
    later(650, () => {
      setQuestion(next);
      setPrevious(null);
      setRankedWith(rerank);
      setPhase("ready");
    });
  };

  const toggleRerank = (on: boolean) => {
    setRerank(on);
    setPhase("reranking");
    const before = new Map(results.map((item, index) => [item.passage.id, index + 1]));
    later(on ? 700 : 300, () => {
      setPrevious(before);
      setRankedWith(on);
      setPhase("ready");
    });
  };

  const top = results[0];
  const status =
    phase === "searching"
      ? "Searching the knowledge base"
      : phase === "reranking"
        ? "Reranking the results"
        : results.length === 0
          ? "No passage matched. Try other words."
          : `${results.length} passages found${rankedWith ? " and reranked" : ""}. Top match: ${top?.passage.source}.`;

  return (
    <div className="flex flex-col gap-4 p-5">
      <form
        className="flex flex-col gap-2 @md:flex-row"
        onSubmit={(event) => {
          event.preventDefault();
          search();
        }}
      >
        <label htmlFor={inputId} className="sr-only">
          Question to test
        </label>
        <Input id={inputId} value={draft} onChange={(event) => setDraft(event.target.value)} className="min-w-0 flex-1" />
        <Button type="submit" disabled={phase === "searching" || draft.trim() === ""}>
          <SearchIcon aria-hidden="true" />
          Search
        </Button>
      </form>

      <div className="flex flex-wrap items-center justify-between gap-3">
        <p role="status" className="flex min-w-0 items-center gap-2 text-sm text-muted-foreground">
          {phase === "ready" ? null : <LoaderIcon aria-hidden="true" className="size-4 shrink-0 motion-safe:animate-spin" />}
          <span className="truncate">{status}</span>
        </p>
        <label htmlFor={rerankId} className="flex cursor-pointer items-center gap-2 text-sm">
          Rerank results
          <Switch id={rerankId} checked={rerank} onCheckedChange={toggleRerank} disabled={phase !== "ready"} />
        </label>
      </div>

      <ol aria-label="Ranked passages" className="group/results flex flex-col gap-2" aria-busy={phase !== "ready"}>
        {results.map((result, index) => (
          <ResultItem
            key={result.passage.id}
            result={result}
            rank={index + 1}
            previousRank={previous?.get(result.passage.id) ?? null}
            showChange={previous !== null && phase === "ready"}
            open={openId === result.passage.id}
            onToggle={() => setOpenId(openId === result.passage.id ? null : result.passage.id)}
          />
        ))}
      </ol>
    </div>
  );
}

