/** Props for one ranked passage. */
export interface ResultItemProps {
  result: Ranked;
  rank: number;
  /** The rank before the rerank, or null when there was no earlier ranking or the passage is new to the list. */
  previousRank: number | null;
  showChange: boolean;
  open: boolean;
  onToggle: () => void;
}

// Critically damped: 2 * sqrt(500) is about 45, so a result slides to its new rank with no bounce.
const MOVE: Transition = { type: "spring", stiffness: 500, damping: 45, mass: 1 };
const TWO_PLACES: Intl.NumberFormatOptions = { minimumFractionDigits: 2, maximumFractionDigits: 2 };
const HUES = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"] as const;

/** The words for a move between ranks. */
function changeText(rank: number, previousRank: number | null) {
  if (previousRank === null) return "New";
  if (previousRank === rank) return "Same";
  return previousRank > rank ? `Up ${previousRank - rank}` : `Down ${rank - previousRank}`;
}

/**
 * One passage in the test results: its rank, a score bar and figure that
 * roll, the source it came from, and the words it matched. It slides to a new
 * rank after a rerank, and opens to show the full passage.
 */
export function ResultItem({ result, rank, previousRank, showChange, open, onToggle }: ResultItemProps) {
  const reduceMotion = useReducedMotion();
  const panelId = useId();
  const hue = HUES[PASSAGES.findIndex((passage) => passage.id === result.passage.id) % HUES.length];
  const change = changeText(rank, previousRank);
  const moved = change.startsWith("Up") ? "good" : change.startsWith("Down") ? "bad" : null;

  return (
    <motion.li
      layout="position"
      transition={reduceMotion ? { duration: 0 } : MOVE}
      className="rounded-xl border border-border bg-card motion-safe:transition-opacity group-hover/results:opacity-60 hover:opacity-100! focus-within:opacity-100!"
    >
      <Button
        variant="ghost"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={onToggle}
        size="sm"
        className="w-full justify-start"
      >
<span className="flex w-full flex-col items-stretch gap-2 px-4 py-3 text-left font-normal whitespace-normal">
        <span className="flex items-center gap-3">
          <span className="w-5 shrink-0 text-sm font-semibold tabular-nums">{rank}</span>
          <span className="min-w-0 flex-1 truncate text-sm font-medium">
            {result.passage.source}
            <span className="font-normal text-muted-foreground">, {result.passage.where}</span>
          </span>
          <AnimatePresence initial={false} mode="popLayout">
            {showChange ? (
              <motion.span
                key={change}
                initial={reduceMotion ? false : { opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.2, delay: reduceMotion ? 0 : 0.25 }}
                className={cn("shrink-0 text-xs font-medium", moved ? STATUS_TEXT[moved] : "text-muted-foreground")}
              >
                {change}
              </motion.span>
            ) : null}
          </AnimatePresence>
          <ChevronDownIcon
            aria-hidden="true"
            className={cn("size-4 shrink-0 text-muted-foreground motion-safe:transition-transform", open && "rotate-180")}
          />
        </span>
        <span className="flex items-center gap-3 pl-8">
          <span aria-hidden="true" className="relative h-1.5 flex-1 overflow-hidden rounded-full bg-muted">
            <span
              className={cn("absolute inset-y-0 left-0 rounded-full w-(--w) motion-safe:transition-all motion-safe:duration-500", hue)}
              style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--w": `${result.score * 100}%` } as VarStyle
              }
            />
          </span>
          <span className="w-9 text-right text-xs tabular-nums">
            <span className="sr-only">Score </span>
            <NumberTicker value={result.score} format={TWO_PLACES} />
          </span>
        </span>
        <span className={cn("pl-8 text-sm text-muted-foreground", open ? "hidden" : "line-clamp-2")}>{result.passage.text}</span>
        <span className="flex flex-wrap items-center gap-1.5 pl-8 text-xs text-muted-foreground">
          Matched on
          {result.matched.map((word) => (
            <span key={word} className="rounded-md border border-border px-1.5 py-0.5 text-foreground">
              {word}
            </span>
          ))}
        </span>
      </span>
</Button>
      <Reveal open={open} id={panelId} className="px-4 pb-4 pl-12">
        <p className="text-sm leading-relaxed">{result.passage.text}</p>
      </Reveal>
    </motion.li>
  );
}

