/** Props for one source in the list. */
export interface SourceRowProps {
  source: Source;
  onRetry: () => void;
}

/** The stage a source is in now, in words. */
function stageWord(source: Source) {
  const stage = STAGES[Math.min(STAGES.length - 1, Math.floor(source.progress / 25))] ?? "Index";
  if (source.state === "done") return "Ready to search";
  if (source.state === "failed") return source.error ?? `${stage} failed`;
  return `${stage === "Embed" ? "Embedding" : stage === "Index" ? "Indexing" : stage === "Parse" ? "Parsing" : "Chunking"}, ${Math.round(source.progress)}%`;
}

/**
 * One source: its name and size, the four-stage pipeline, and its state. A
 * failed source has a Retry button; one at work shows its percent.
 */
export function SourceRow({ source, onRetry }: SourceRowProps) {
  const Icon = source.kind === "page" ? GlobeIcon : FileIcon;
  return (
    <li className="grid grid-cols-[1fr_auto] items-center gap-x-4 gap-y-2 px-5 py-3 @2xl:grid-cols-[1fr_11rem_5.5rem]">
      <div className="flex min-w-0 items-start gap-3">
