          <p className={cn("truncate text-xs", source.state === "failed" ? STATUS_TEXT.bad : "text-muted-foreground")}>
            {source.state === "failed"
              ? source.error
              : `${source.pages} pages, ${formatCount(source.passages)} passages, ${formatTokens(source.tokens)} tokens, ${source.state === "indexing" ? "syncing" : `added ${source.added}`}`}
          </p>
        </div>
