        <span className="sr-only">{stageWord(source)}</span>
        {source.state === "done" ? (
          <CircleCheckIcon aria-hidden="true" className={cn("size-4", STATUS_TEXT.good)} />
        ) : source.state === "failed" ? (
          <Button variant="outline" size="sm" onClick={onRetry} aria-label={`Retry ${source.name}`}>
            <RefreshIcon aria-hidden="true" />
            Retry
