import { STAGE_FILL, STAGES, type SourceState } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the four-stage pipeline of one source. */
export interface PipelineBarProps {
  /** Progress through all four stages, from 0 to 100. */
  progress: number;
  state: SourceState;
  className?: string;
}

const SHARE = 100 / STAGES.length;

/**
 * Four short segments, one per stage: parse, chunk, embed, index. A done
 * stage is filled in its own hue, the stage at work fills part way, and the
 * stage where a failed source stopped turns orange. Decorative: the row says the state in words.
 */
export function PipelineBar({ progress, state, className }: PipelineBarProps) {
  const stuck = Math.min(STAGES.length - 1, Math.floor(progress / SHARE));
  return (
    <span aria-hidden="true" className={cn("grid grid-cols-4 gap-1", className)}>
      {STAGES.map((stage, index) => {
        const filled = Math.min(1, Math.max(0, (progress - index * SHARE) / SHARE));
        const failedHere = state === "failed" && index === stuck;
        return (
          <span key={stage} className="relative h-1.5 overflow-hidden rounded-full bg-muted">
            <span
              className={cn(
                "absolute inset-y-0 left-0 rounded-full w-(--w) motion-safe:transition-all motion-safe:duration-500",
                failedHere ? cn("bg-current", STATUS_TEXT.bad) : STAGE_FILL[index],
              )}
              style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--w": `${(failedHere ? Math.max(filled, 0.35) : filled) * 100}%` } as VarStyle
              }
            />
          </span>
        );
      })}
    </span>
  );
}
